#pragma once

#include <fstream>
#include <map>
#include <string>
#include <vector>

#include <glm/glm.hpp>
#include <nlohmann/json.hpp>

// Ship design catalog (runtime copy GENERATED by tools/colonization_lab/ship_designer.py
// from canon/ship_designs.json): ship models of 3126 with their installed equipment,
// derived physics and functional schematics. One stable passport id per model; the
// equipment products are shared by every model that installs them.
//
// The catalog owns every string. Descriptors built from it (GenericShipDescriptorBuilder)
// may hold string_views into it, so a catalog instance must outlive them - the process
// catalog (ShipDesignCatalog::instance()) is never destroyed.
namespace game::catalog::ships
{

struct ShipDesignProduct
{
    std::string id;
    std::string category;      // drive, reactor, service_reactor, radiator, coolant_loop, jump_core, tank, rcs, ...
    std::string manufacturer;  // manufacturer id (industry.json)
    std::string name;
    std::string model;
    double massTonnes = 0.0;
    double priceCr = 0.0;
    double overhaulHours = 0.0;
    double lifeHours = 0.0;
    nlohmann::json params;     // category-specific ratings (thrust_mn, input_mw, eff, mwe, area_m2, ...)

    [[nodiscard]] double number(const char* key, double fallback = 0.0) const
    {
        return params.contains(key) && params[key].is_number() ? params[key].get<double>() : fallback;
    }
    [[nodiscard]] std::string text(const char* key) const
    {
        return params.contains(key) && params[key].is_string() ? params[key].get<std::string>() : std::string();
    }
};

struct ShipDesignInstalledItem
{
    std::string code;          // installation position, e.g. "L-900-A1A1"
    std::string productId;
    std::string category;
    int quantity = 0;
    std::vector<glm::dvec3> positions;   // normalized body positions (+X right, +Y up, +Z aft)
};

struct ShipDesignSchematicNode
{
    std::string code;
    std::string productId;
    std::string category;
    int quantity = 0;
    std::string repairLevel;   // crew | station | yard | factory
    bool lineReplaceable = false;
    double replaceHours = 0.0;
};

struct ShipDesignSchematicEdge
{
    std::string network;       // power_propulsion | power_service | coolant | fuel | data | life
    std::string source;
    std::string target;
};

struct ShipDesign
{
    std::string id;            // passport stable id
    std::string designation;
    std::string name;
    std::string shipClass;
    std::string manufacturer;
    std::string runtime;       // "generic" or "existing:<descriptor>:<model>"
    std::string physicalModel; // AssistedI ... NewtonianX
    std::string law;
    std::string form;
    glm::dvec3 envelopeMeters {0.0};   // length, width, height
    double dryMassTonnes = 0.0;
    int crew = 0;
    int passengers = 0;
    double cargoTonnes = 0.0;
    int containerSlots = 0;
    int enduranceDays = 0;
    double thrustMN = 0.0;
    double accelLoadedG = 0.0;
    double accelLightG = 0.0;
    double sustainableThrust01 = 1.0;
    double driveEmitterDiameterM = 0.0;
    double propulsionMWe = 0.0;
    double serviceMWe = 0.0;
    double hotelMW = 0.0;
    double reactorPadM2 = 0.0;
    double radiatorAreaM2 = 0.0;
    double radiatorTemperatureK = 0.0;
    double radiatorEmissivity = 0.9;
    double coolantCapacityMW = 0.0;
    std::string radiatorMaterial;
    std::vector<ShipDesignInstalledItem> installed;
    std::vector<ShipDesignSchematicNode> schematicNodes;
    std::vector<ShipDesignSchematicEdge> schematicEdges;
    std::vector<std::string> singlePointsOfFailure;

    [[nodiscard]] const ShipDesignInstalledItem* firstOf(const std::string& category) const
    {
        for (const auto& item : installed)
            if (item.category == category)
                return &item;
        return nullptr;
    }
    [[nodiscard]] int countOf(const std::string& category) const
    {
        int n = 0;
        for (const auto& item : installed)
            if (item.category == category)
                n += item.quantity;
        return n;
    }
};

class ShipDesignCatalog
{
public:
    [[nodiscard]] static const ShipDesignCatalog& instance()
    {
        static const ShipDesignCatalog* catalog = [] {
            auto* c = new ShipDesignCatalog();      // intentionally never destroyed (descriptors view its strings)
            c->load("assets/data/ships/ship_catalog_3126.json");
            return c;
        }();
        return *catalog;
    }

    bool load(const std::string& path)
    {
        std::ifstream in(path);
        if (!in)
            return false;
        nlohmann::json root;
        try
        {
            in >> root;
        }
        catch (...)
        {
            return false;
        }
        m_products.clear();
        m_ships.clear();
        for (const auto& j : root.value("products", nlohmann::json::array()))
        {
            ShipDesignProduct p;
            p.id = j.value("id", std::string());
            p.category = j.value("cat", std::string());
            p.manufacturer = j.value("mfr", std::string());
            p.name = j.value("name", std::string());
            p.model = j.value("model", std::string());
            p.massTonnes = j.value("mass_t", 0.0);
            p.priceCr = j.value("price_cr", 0.0);
            p.overhaulHours = j.value("overhaul_h", 0.0);
            p.lifeHours = j.value("life_h", 0.0);
            p.params = j;
            m_products[p.id] = std::move(p);
        }
        for (const auto& j : root.value("ships", nlohmann::json::array()))
        {
            ShipDesign s;
            s.id = j.value("id", std::string());
            s.designation = j.value("designation", std::string());
            s.name = j.value("name", std::string());
            s.shipClass = j.value("cls", std::string());
            s.manufacturer = j.value("manufacturer", std::string());
            s.runtime = j.value("runtime", std::string());
            s.physicalModel = j.value("physical_model", std::string());
            s.law = j.value("law", std::string());
            s.form = j.value("form", std::string());
            if (j.contains("envelope_m") && j["envelope_m"].size() == 3)
                s.envelopeMeters = {j["envelope_m"][0].get<double>(), j["envelope_m"][1].get<double>(), j["envelope_m"][2].get<double>()};
            s.dryMassTonnes = j.value("dry_mass_t", 0.0);
            s.crew = j.value("crew", 0);
            s.passengers = j.value("passengers", 0);
            s.cargoTonnes = j.value("cargo_t", 0.0);
            s.containerSlots = j.value("c20", 0);
            s.enduranceDays = j.value("endurance_days", 0);
            const auto& prop = j.value("propulsion", nlohmann::json::object());
            s.thrustMN = prop.value("thrust_mn", 0.0);
            s.accelLoadedG = prop.value("accel_g_loaded", 0.0);
            s.accelLightG = prop.value("accel_g_light", 0.0);
            s.sustainableThrust01 = prop.value("sustainable_thrust01", 1.0);
            s.driveEmitterDiameterM = prop.value("drive_emitter_diameter_m", 0.0);
            const auto& pw = j.value("power", nlohmann::json::object());
            s.propulsionMWe = pw.value("propulsion_mwe", 0.0);
            s.serviceMWe = pw.value("service_mwe", 0.0);
            s.hotelMW = pw.value("hotel_mw", 0.0);
            s.reactorPadM2 = pw.value("reactor_pad_m2", 0.0);
            const auto& th = j.value("thermal", nlohmann::json::object());
            s.radiatorAreaM2 = th.value("radiator_area_m2", 0.0);
            s.radiatorTemperatureK = th.value("radiator_temp_k", 0.0);
            s.radiatorEmissivity = th.value("radiator_eps", 0.9);
            s.coolantCapacityMW = th.value("coolant_capacity_mw", 0.0);
            s.radiatorMaterial = th.value("radiator_material", std::string());
            for (const auto& it : j.value("installed", nlohmann::json::array()))
            {
                ShipDesignInstalledItem item;
                item.code = it.value("code", std::string());
                item.productId = it.value("product", std::string());
                item.category = it.value("cat", std::string());
                item.quantity = it.value("qty", 0);
                for (const auto& p : it.value("positions", nlohmann::json::array()))
                    if (p.size() == 3)
                        item.positions.push_back({p[0].get<double>(), p[1].get<double>(), p[2].get<double>()});
                s.installed.push_back(std::move(item));
            }
            const auto& sc = j.value("schematic", nlohmann::json::object());
            for (const auto& n : sc.value("nodes", nlohmann::json::array()))
                s.schematicNodes.push_back({n.value("code", std::string()), n.value("product", std::string()), n.value("cat", std::string()),
                                            n.value("qty", 0), n.value("repair_level", std::string()), n.value("line_replaceable", false),
                                            n.value("replace_hours", 0.0)});
            for (const auto& e : sc.value("edges", nlohmann::json::array()))
                s.schematicEdges.push_back({e.value("net", std::string()), e.value("src", std::string()), e.value("dst", std::string())});
            for (const auto& c : sc.value("single_points_of_failure", nlohmann::json::array()))
                s.singlePointsOfFailure.push_back(c.get<std::string>());
            m_ships.push_back(std::move(s));
        }
        return !m_ships.empty();
    }

    [[nodiscard]] const std::vector<ShipDesign>& ships() const noexcept { return m_ships; }
    [[nodiscard]] const ShipDesign* findShip(const std::string& id) const
    {
        for (const auto& s : m_ships)
            if (s.id == id)
                return &s;
        return nullptr;
    }
    [[nodiscard]] const ShipDesignProduct* findProduct(const std::string& id) const
    {
        const auto it = m_products.find(id);
        return it == m_products.end() ? nullptr : &it->second;
    }

private:
    std::map<std::string, ShipDesignProduct> m_products;
    std::vector<ShipDesign> m_ships;
};

} // namespace game::catalog::ships
